/**
 * Slack deep links for threads / messages.
 */
/** Build a web permalink that opens a Slack thread in the browser. */
export function slackThreadPermalink(args) {
    const channelId = args.channelId.trim();
    const threadTs = args.threadTs.trim();
    if (channelId === "" || threadTs === "") {
        return null;
    }
    const teamId = args.teamId?.trim();
    if (teamId !== undefined && teamId !== "" && teamId !== "unknown") {
        // Client deep link opens the thread pane in the right workspace.
        return `https://app.slack.com/client/${encodeURIComponent(teamId)}/${encodeURIComponent(channelId)}/thread/${encodeURIComponent(channelId)}-${encodeURIComponent(threadTs)}`;
    }
    const pTs = `p${threadTs.replace(".", "")}`;
    return `https://app.slack.com/archives/${encodeURIComponent(channelId)}/${pTs}?thread_ts=${encodeURIComponent(threadTs)}`;
}
